const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value, defaultValue = false) => {
  if (value === null || value === undefined || value === '') return defaultValue;
  if (typeof value === 'boolean') return value;

  const normalized = String(value).trim().toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(normalized)) return true;
  if (['false', '0', 'no', 'off'].includes(normalized)) return false;

  return defaultValue;
};

const clinic_name = text(input.clinic_name);
const mobile = text(input.mobile);
const status_filter = text(input.status_filter || 'active').toLowerCase();
const include_past = toBoolean(input.include_past, false);

const parsedLimit = Number(input.limit ?? 10);
const limit = Number.isInteger(parsedLimit) ? parsedLimit : 10;

const allowedStatuses = [
  'active',
  'all',
  'pending',
  'confirmed',
  'cancelled',
  'completed',
  'no_show',
  'rescheduled',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!mobile) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل بیمار الزامی است.',
  });
}

if (mobile && !/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل باید فقط شامل اعداد و در صورت نیاز علامت + باشد.',
  });
}

if (!allowedStatuses.includes(status_filter)) {
  errors.push({
    field: 'status_filter',
    message: `status_filter باید یکی از این مقادیر باشد: ${allowedStatuses.join(', ')}`,
  });
}

if (!Number.isInteger(limit) || limit < 1 || limit > 50) {
  errors.push({
    field: 'limit',
    message: 'limit باید یک عدد صحیح بین 1 و 50 باشد.',
  });
}

return [
  {
    json: {
      clinic_name,
      mobile,
      status_filter,
      include_past,
      limit,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات درخواست ناقص یا نامعتبر است.',
      appointment_count: 0,
      appointments: [],
      errors: $json.errors ?? [],
    },
  },
];
